function averageVectors(vectors) {
  const dim = vectors[0].length;
  const avg = new Array(dim).fill(0);
  for (const v of vectors) {
    for (let i = 0; i < dim; i++) avg[i] += v[i];
  }
  for (let i = 0; i < dim; i++) avg[i] /= vectors.length;
  return avg;
}

export async function onRequestGet(context) {
  const { env } = context;

  const types = Object.keys(TYPE_EXAMPLES);
  const allSentences = [];
  const sentenceTypeIndex = [];

  for (const type of types) {
    for (const sentence of TYPE_EXAMPLES[type]) {
      allSentences.push(sentence);
      sentenceTypeIndex.push(type);
    }
  }

  const result = await env.AI.run(EMBED_MODEL, { text: allSentences });
  const vectors = result?.data ?? [];

  const grouped = {};
  for (let i = 0; i < vectors.length; i++) {
    const type = sentenceTypeIndex[i];
    if (!grouped[type]) grouped[type] = [];
    grouped[type].push(vectors[i]);
  }

  const anchors = {};
  for (const type of types) {
    if (grouped[type]?.length) {
      anchors[type] = averageVectors(grouped[type]);
    }
  }

  // 直接返回可以复制粘贴进代码的格式
  return new Response(JSON.stringify(anchors, null, 2), {
    headers: { "Content-Type": "application/json" },
  });
}
